/**
 * The vocabulary of the screens behind a lazy route: the back office, the printed documents and
 * the operator portal. Registered through `I18nService.extend` by the component that owns each
 * of those routes, so it travels in that route's chunk and never in a till's download.
 *
 * <p>A key belongs here only when no always-loaded file names it — see the note in
 * `translations.ts`. Adding a key used by both places to this file is the mistake to avoid: it
 * renders as its own name on the register.</p>
 */
